273	    /**
274	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
275	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
276	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
277	     * postcode is checked against its city's region, a registration date in the future is rejected,
278	     * and the effective registration date (the supplied one, or today when none was given) is rolled
279	     * onto a business day and stored back on the owner. Returns {@code null} once the owner is valid
280	     * and normalized, or the {@link HttpStatus} the create must fail with ({@code 400 Bad Request})
281	     * otherwise.
282	     */
283	    private HttpStatus normalizeAndValidate(Owner owner) {
284	        if (!normalizeAddress(owner)) {
285	            return HttpStatus.BAD_REQUEST;
286	        }
287	        String telephone = toE164(owner.getTelephone());
288	        if (telephone == null) {
289	            return HttpStatus.BAD_REQUEST;
290	        }
291	        owner.setTelephone(telephone);
292	        if (isDisposableEmail(owner.getEmail())) {
293	            return HttpStatus.BAD_REQUEST;
294	        }
295	        if (!owner.isPostcodeValid()) {
296	            return HttpStatus.BAD_REQUEST;
297	        }
298	        if (owner.getRegistrationDate() != null
299	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
300	            return HttpStatus.BAD_REQUEST;
301	        }
302	        LocalDate effectiveDate = owner.getRegistrationDate() != null
303	            ? owner.getRegistrationDate() : LocalDate.now();
304	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
305	        return null;
306	    }
307	
308	    /**
309	     * Normalize the owner's supplied address into its canonical stored form and report whether an
310	     * address was supplied at all. The owner may supply its address either as the structured
311	     * {@code addressLine1}/{@code addressLine2} fields or as the flat {@code address} field, which is
312	     * kept for backward compatibility; the structured form is preferred whenever a non-blank
313	     * {@code addressLine1} is present. Each supplied field is run through the {@link AddressNormalizer}
314	     * (trimmed, whitespace-collapsed, upper-cased, common street-type abbreviations expanded). When the
315	     * structured form is used, the normalized {@code addressLine1} and {@code addressLine2} are stored
316	     * back and the composed {@link Owner#getAddress() address} becomes the normalized
317	     * {@code addressLine1} with a single space and the normalized {@code addressLine2} appended when an
318	     * {@code addressLine2} is present; when the flat form is used, the normalized flat address is
319	     * stored and no structured lines are kept. Returns {@code true} once a non-blank address has been
320	     * normalized and stored, or {@code false} when neither form supplied an address, in which case the
321	     * create must be rejected with {@code 400 Bad Request}.
322	     */
323	    private boolean normalizeAddress(Owner owner) {
324	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
325	        if (!line1.isEmpty()) {
326	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
327	            owner.setAddressLine1(line1);
328	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
329	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
330	            return true;
331	        }
332	        String address = addressNormalizer.normalize(owner.getAddress());
333	        if (address.isEmpty()) {
334	            return false;
335	        }
336	        owner.setAddressLine1(null);
337	        owner.setAddressLine2(null);
338	        owner.setAddress(address);
339	        return true;

